/**
 * 글꼴 공방 (F26-m 2단계, 2026-10-25) — 관리자 전용 `/admin/maker/font` 의 바탕 글꼴 목록과 화면 문구 «한 곳».
 *
 * 🔴 **이 파일은 글꼴 공방 화면(`components/maker/FontStudio.tsx`)만 가져옵니다.** 머리말·꼬리말·공통 레이아웃·공개 페이지·
 * `config/site.ts`·`config/flags.ts` 는 이 파일을 import 하지 않습니다(F34 — 손님 첫 화면 무게 0). 목록이 170여 줄이라
 * 공통 부품이 한 줄이라도 가져오면 모든 페이지 공용 JS 에 실립니다. 공통 부품이 읽을 값이 생기면 `config/flags.ts` 에 두세요.
 *
 * 🔴 **글꼴 파일은 우리 서버·저장소에 올리지 않습니다**(사람 결정 2026-10-24). 아래 `url` 은 배포처 주소이고, 관리자 브라우저가
 * 바로 읽습니다(구글 폰트 = jsdelivr `gh/google/fonts`, 나눔 = `hangeul.naver.com`·`campaign-cdn.pstatic.net`, GitHub OFL = jsdelivr `gh/<저장소>`).
 * 2026-10-25 에 전 주소를 `Origin` 을 붙여 요청해 **응답 200(나눔손글씨는 부분 요청 206)·`Access-Control-Allow-Origin: *`** 를 확인했고,
 * 나눔손글씨 109종을 뺀 68종은 파일을 통째로 받아 fontTools 로 한글 음절 수를 셌습니다(`syllables` 가 그 값).
 *
 * 🔴 **목록 부분(아래 «생성» 표시 사이)은 손으로 고치지 마세요** — `node scripts/gen-fontlab.mjs` 가 형제 저장소
 * `SusannaDesigner` 의 조사 자료(`study/2026-10-24_hangul-font/page/fonts/catalog.json` · `refs/fonts/_more.json` ·
 * `refs/fonts/_research/nanum_clova_urls.tsv`)에서 다시 씁니다. 주소 규칙·뺀 글꼴과 그 이유도 그 스크립트에 있습니다.
 *
 * 라이선스: 남은 글꼴은 전부 SIL OFL 1.1 입니다. 받은 TTF 에는 원작 저작권(`copyright`)과 OFL 고지가 name 표 0·13·14 번으로 들어가고,
 * 예약 이름(`rfn`)이 든 폰트 이름은 막습니다(OFL 3조). 법률 검토가 아니라 원문을 직접 읽은 범위입니다.
 */
import { site } from "./site";

export type FontLabCategory = "hand" | "display" | "sans" | "serif";

export const fontLabCategories: { key: FontLabCategory | "all"; label: string }[] = [
  { key: "all", label: "전체" },
  { key: "hand", label: "손글씨" },
  { key: "display", label: "장식" },
  { key: "sans", label: "고딕" },
  { key: "serif", label: "명조" },
];

export type FontLabFont = {
  /** 시제품 목록과 같은 번호 (`g-` 구글 · `ge-` 구글 추가분 · `n-` 나눔 · `gh-` GitHub) */
  id: string;
  name: string;
  category: FontLabCategory;
  /** 배포처 원본 파일 주소 — 브라우저가 바로 받습니다(CORS `*` 확인) */
  url: string;
  /** 배포처 소개 페이지 — 근거 */
  source: string;
  license: "OFL-1.1";
  licenseUrl: string;
  /** 원작 저작권 문구(글꼴 파일 name 표 0번) — 받은 TTF 에 그대로 넣습니다 */
  copyright: string;
  /** 예약 이름(Reserved Font Name) — 폰트 이름에 들어가면 막습니다 */
  rfn: string[];
  /** 원본 파일의 한글 음절 수 (11,172 = 전부) */
  syllables: number;
  /** 미리보기 그림 (`public/images/fontlab/`) */
  preview: string;
};

